import crypto from "node:crypto"
import { NextRequest, NextResponse } from "next/server"
import { sanityClient } from "@/lib/sanity/client"
import { extractEventName, normalizeChat, normalizeTicket } from "@/lib/tawk/normalize"

export const runtime = "nodejs"

// Verified against tawk.io's own docs once a real signed payload is seen —
// header name and algorithm are a best guess until then (see comment below).
function verifySignature(rawBody: string, signature: string | null, secret: string | undefined) {
  if (!secret || !signature) return false
  const expected = crypto.createHmac("sha256", secret).update(rawBody).digest("hex")
  const expectedBuf = Buffer.from(expected)
  const signatureBuf = Buffer.from(signature)
  if (expectedBuf.length !== signatureBuf.length) return false
  return crypto.timingSafeEqual(expectedBuf, signatureBuf)
}

export async function POST(req: NextRequest) {
  const rawBody = await req.text()
  const signature =
    req.headers.get("x-tawk-signature") ?? req.headers.get("x-tawk-webhook-signature")
  const secret = process.env.TAWK_WEBHOOK_SECRET
  const signatureValid = verifySignature(rawBody, signature, secret)

  // Reject unsigned/invalid requests by default. Set TAWK_WEBHOOK_ALLOW_UNSIGNED=true
  // locally while calibrating against a real tawk.io test event (see setup notes).
  const allowUnsigned =
    process.env.NODE_ENV !== "production" || process.env.TAWK_WEBHOOK_ALLOW_UNSIGNED === "true"
  if (!signatureValid && !allowUnsigned) {
    return NextResponse.json({ error: "Invalid signature" }, { status: 401 })
  }

  let body: unknown
  try {
    body = JSON.parse(rawBody)
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 })
  }

  const event = extractEventName(body)
  const headers: Record<string, string> = {}
  req.headers.forEach((value, key) => {
    headers[key] = value
  })

  const tx = sanityClient.transaction()

  tx.create({
    _type: "tawkEvent",
    event,
    receivedAt: new Date().toISOString(),
    signatureValid,
    headers,
    body,
  })

  const chat = normalizeChat(body, event)
  if (chat) tx.createOrReplace(chat)

  const ticket = normalizeTicket(body, event)
  if (ticket) tx.createOrReplace(ticket)

  try {
    await tx.commit()
  } catch (error) {
    console.error("Failed to persist tawk webhook event:", error)
    return NextResponse.json({ error: "Storage failed" }, { status: 500 })
  }

  return NextResponse.json({ received: true, event, signatureValid })
}

export async function GET() {
  return NextResponse.json({ status: "ok" })
}
